To build a FIPS-compliant password storage system in Node.js for an EHR/EPCS application, you must use Node's built-in `crypto` module. Beneath the hood, Node.js uses **OpenSSL** for its cryptographic operations. 

If your server is running a FIPS-validated OpenSSL module (e.g., on Red Hat Enterprise Linux or Ubuntu Pro with FIPS enabled), Node’s native `crypto` functions will route directly through those government-approved algorithms.

Here is a complete, production-ready example of how to implement this according to **NIST SP 800-132** and **NIST SP 800-63B** guidelines, including **HMAC Peppering** and **Constant-Time Verification**.

### 1. Environment Prerequisite: Enabling FIPS in Node.js
Before running the code, a strict DEA EPCS audit requires proof that FIPS mode is active. You must start your Node application with the `--force-fips` flag (assuming your underlying OS/OpenSSL is FIPS-capable):

```bash
node --force-fips app.js
```

### 2. The FIPS-Compliant Password Service (`authService.js`)

```javascript
const crypto = require('crypto');
const util = require('util');

// Promisify pbkdf2 so we don't block the Node.js Event Loop during hospital shift changes!
const pbkdf2Async = util.promisify(crypto.pbkdf2);

// --- NIST & OWASP COMPLIANT CONFIGURATION ---
const CONFIG = {
  // NIST SP 800-132 requires a minimum salt length of 128 bits (16 bytes). We use 32 bytes.
  SALT_BYTES: 32, 
  // OWASP recommendation for PBKDF2-HMAC-SHA512 is at least 210,000 to 310,000 iterations.
  ITERATIONS: 310000, 
  // 512 bits (64 bytes) output length matching SHA-512
  KEY_LENGTH: 64, 
  // FIPS 180-4 approved hash function
  DIGEST: 'sha512' 
};

/**
 * Verifies that the Node.js runtime is strictly operating in FIPS mode.
 * In an EPCS system, the app should refuse to boot if FIPS is off.
 */
function enforceFipsMode() {
  if (crypto.getFips() !== 1) {
    // WARNING: For local testing on a normal Mac/PC, comment out the throw line below, 
    // as standard consumer machines don't have the FIPS OpenSSL module installed.
    console.warn("⚠️  WARNING: Running outside of FIPS mode. Do not use in EPCS Production!");
    // throw new Error("FATAL: Application must run in FIPS mode for DEA EPCS compliance.");
  } else {
    console.log("✅ FIPS 140-2/3 Cryptographic Mode Verified.");
  }
}

/**
 * Applies a "Pepper" (Secret Key) to the password using FIPS-approved HMAC.
 * In production, 'pepperSecret' should be fetched at boot from an HSM (e.g., AWS CloudHSM / KMS).
 */
function applyPepper(password, pepperSecret) {
  if (!pepperSecret || pepperSecret.length < 32) {
    throw new Error("Invalid Pepper: Secret key from HSM/KMS must be at least 256 bits.");
  }
  return crypto
    .createHmac(CONFIG.DIGEST, pepperSecret)
    .update(password)
    .digest('hex');
}

/**
 * Hashes a doctor's password for storage.
 * Output format: pbkdf2_sha512$iterations$salt$hash
 */
async function hashPassword(plainTextPassword, pepperSecret) {
  // 1. Pre-hash/combine the password with the HSM Pepper via HMAC
  const pepperedPassword = applyPepper(plainTextPassword, pepperSecret);

  // 2. Generate a cryptographically strong random salt (FIPS DRBG compliant)
  const salt = crypto.randomBytes(CONFIG.SALT_BYTES).toString('hex');

  // 3. Run PBKDF2 asynchronously
  const derivedKey = await pbkdf2Async(
    pepperedPassword,
    salt,
    CONFIG.ITERATIONS,
    CONFIG.KEY_LENGTH,
    CONFIG.DIGEST
  );

  const hash = derivedKey.toString('hex');

  // 4. Return a self-contained string (similar to bcrypt format) for the database.
  // Storing iterations in the string allows you to increase the count in the future 
  // without breaking existing users' passwords.
  return `pbkdf2_${CONFIG.DIGEST}$${CONFIG.ITERATIONS}$${salt}$${hash}`;
}

/**
 * Verifies a doctor's password during login or prescription signing.
 */
async function verifyPassword(plainTextPassword, storedDbString, pepperSecret) {
  // 1. Parse the stored string from the database
  const parts = storedDbString.split('$');
  if (parts.length !== 4) {
    throw new Error("Invalid stored password hash format.");
  }

  const [algorithm, iterationsStr, salt, originalHashHex] = parts;
  const digest = algorithm.replace('pbkdf2_', '');
  const iterations = parseInt(iterationsStr, 10);
  const originalHashBuffer = Buffer.from(originalHashHex, 'hex');

  // 2. Apply the same HSM Pepper to the incoming password attempt
  const pepperedPassword = applyPepper(plainTextPassword, pepperSecret);

  // 3. Hash the attempt using the EXACT parameters stored with the original hash
  const attemptedKeyBuffer = await pbkdf2Async(
    pepperedPassword,
    salt,
    iterations,
    originalHashBuffer.length,
    digest
  );

  // 4. CRITICAL: Use Constant-Time comparison to prevent timing side-channel attacks
  return crypto.timingSafeEqual(originalHashBuffer, attemptedKeyBuffer);
}

// --- EXAMPLE USAGE ---
async function runEhrAuthDemo() {
  enforceFipsMode();

  // Simulated secret fetched from a FIPS 140-3 Level 3 Hardware Security Module (HSM)
  const HSM_PEPPER_SECRET = process.env.HSM_PEPPER || "a9f8d7s6f5g4h3j2k1l0q9w8e7r6t5y4u3i2o1p0z9x8c7v6b5n4m3";

  const doctorPassword = "CorrectHorseBatteryStaple!99";

  console.log("\n1. Doctor registers / sets EPCS signing password...");
  console.time("Hashing Time");
  const dbStoredValue = await hashPassword(doctorPassword, HSM_PEPPER_SECRET);
  console.timeEnd("Hashing Time");

  console.log("\nStored in Database (VARCHAR/TEXT):");
  console.log(dbStoredValue);

  console.log("\n2. Doctor logs in to prescribe a controlled substance...");
  const isSuccess = await verifyPassword("CorrectHorseBatteryStaple!99", dbStoredValue, HSM_PEPPER_SECRET);
  console.log("Login with correct password:", isSuccess ? "✅ APPROVED" : "❌ DENIED");

  const isFailure = await verifyPassword("WrongPassword123!", dbStoredValue, HSM_PEPPER_SECRET);
  console.log("Login with wrong password:  ", isFailure ? "✅ APPROVED" : "❌ DENIED");
}

runEhrAuthDemo().catch(console.error);
```

### Why this passes a DEA EPCS / FedRAMP Audit:

1.  **Asynchronous Execution (`util.promisify`):** Notice we did *not* use `crypto.pbkdf2Sync()`. In Node.js, synchronous crypto blocks the main single-threaded Event Loop. If you use the synchronous version, one doctor logging in will freeze the entire server for every other doctor for ~250ms. The async version offloads the heavy C++ hashing math to Node's background `libuv` thread pool.
2.  **Cryptographic Agility:** By formatting the database string as `pbkdf2_sha512$310000$salt$hash`, your system is future-proof. If NIST raises the required iteration count to `500,000` next year, you just change `CONFIG.ITERATIONS`. The `verifyPassword` function reads the old `310000` count from the database string to log the doctor in, and you can seamlessly re-hash and upgrade their password in the background.
3.  **NIST SP 800-63B Section 5.1.1.2 Compliance:** That specific section of the federal guidelines states that memorized secrets (passwords) must be salted and hashed using a suitable one-way key derivation function, and specifically recommends performing an additional iteration using a secret key (the `applyPepper` HMAC function) stored separately from the database.
4.  **Side-Channel Resistance:** Using `crypto.timingSafeEqual()` guarantees that the CPU takes the exact same amount of nanoseconds to reject a password whether the attacker got 0 characters right or 99% of the hash right, neutralizing timing attacks.

Yes. Here’s an **Express example for a widget embedded in a cross-site iframe**.

**Important:** `SameSite=None; Secure; HttpOnly` enables cross-site session cookies; it does **not** provide CSRF protection. The example adds a session-bound CSRF token and an exact `Origin` check.

### Scenario

- Parent page: `https://merchant.example`
- Embedded widget: `https://widget.example`
- The widget makes authenticated requests to its own server.

### 1. Configure the session and CSRF checks

Install dependencies:

```bash
npm install express express-session
```

Create `server.mjs`:

```js
import express from "express";
import session from "express-session";
import { randomBytes } from "node:crypto";
import { fileURLToPath } from "node:url";

const app = express();
const WIDGET_ORIGIN = "https://widget.example";
const MERCHANT_ORIGIN = "https://merchant.example";

if (!process.env.SESSION_SECRET) {
  throw new Error("SESSION_SECRET is required");
}

// Assumes exactly one trusted, HTTPS-terminating reverse proxy.
// Adjust this to your actual deployment; don't blindly trust proxies.
app.set("trust proxy", 1);

app.use((req, res, next) => {
  res.set({
    "Content-Security-Policy":
      `default-src 'self'; script-src 'self'; connect-src 'self'; ` +
      `frame-ancestors ${MERCHANT_ORIGIN}; base-uri 'none'; form-action 'self'`,
    "X-Content-Type-Options": "nosniff",
    "Cache-Control": "no-store",
  });
  next();
});

app.use(express.json({ limit: "10kb" }));

app.use(session({
  name: "__Host-session",
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,

  // DEVELOPMENT ONLY: the default in-memory store.
  // Configure a shared production store, such as Redis, before deployment.

  cookie: {
    secure: true,       // Browser sends this cookie only over HTTPS.
    httpOnly: true,     // JavaScript cannot read the cookie.
    sameSite: "none",   // Permit cookie use in a cross-site iframe.
    path: "/",         // Required for the __Host- prefix.
    maxAge: 30 * 60 * 1000,
    // No Domain attribute: also required for __Host-.
  },
}));

app.get("/csrf", (req, res) => {
  req.session.csrfToken ??= randomBytes(32).toString("hex");
  res.json({ csrfToken: req.session.csrfToken });
});

function requireCsrf(req, res, next) {
  // Requests initiated by JavaScript inside the widget iframe have
  // the widget's origin—not the parent merchant's origin.
  if (req.get("Origin") !== WIDGET_ORIGIN) {
    return res.status(403).json({ error: "Invalid origin" });
  }

  const suppliedToken = req.get("X-CSRF-Token");

  if (
    !req.session.csrfToken ||
    !suppliedToken ||
    suppliedToken !== req.session.csrfToken
  ) {
    return res.status(403).json({ error: "Invalid CSRF token" });
  }

  next();
}

app.post("/api/preferences", requireCsrf, (req, res) => {
  // For account changes, also require an authenticated user,
  // check authorization, and validate the request body.
  req.session.compactView = req.body.compactView === true;

  res.json({
    ok: true,
    compactView: req.session.compactView,
  });
});

app.get("/widget", (req, res) => {
  res.sendFile(fileURLToPath(new URL("./widget.html", import.meta.url)));
});

app.get("/widget.js", (req, res) => {
  res.sendFile(fileURLToPath(new URL("./widget.js", import.meta.url)));
});

// Reach this backend through https://widget.example.
app.listen(3000);
```

This deliberately rejects state-changing requests without an `Origin` header. If you support other clients, design their authentication separately rather than simply disabling this check.

### 2. Make requests from inside the iframe

Create `widget.html`:

```html
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <title>Preferences widget</title>
    <script src="/widget.js" defer></script>
  </head>
  <body>
    <button id="save" type="button">Enable compact view</button>
    <p id="status" role="status"></p>
  </body>
</html>
```

Create `widget.js`:

```js
document.querySelector("#save").addEventListener("click", async () => {
  const status = document.querySelector("#status");

  try {
    const tokenResponse = await fetch("/csrf", {
      credentials: "same-origin",
    });

    if (!tokenResponse.ok) throw new Error("Could not obtain CSRF token");

    const { csrfToken } = await tokenResponse.json();

    const response = await fetch("/api/preferences", {
      method: "POST",
      credentials: "same-origin",
      headers: {
        "Content-Type": "application/json",
        "X-CSRF-Token": csrfToken,
      },
      body: JSON.stringify({ compactView: true }),
    });

    if (!response.ok) throw new Error("Save failed");

    status.textContent = "Saved.";
  } catch (error) {
    status.textContent = error.message;
  }
});
```

Although the iframe is embedded cross-site, these `fetch` calls are **same-origin relative to the widget document**. No CORS configuration is needed.

The merchant embeds it with:

```html
<iframe
  src="https://widget.example/widget"
  title="Preferences"
></iframe>
```

### Why this blocks CSRF

An attacker may be able to trigger a request carrying the session cookie. But their page cannot normally read `/csrf` because of the same-origin policy, so it cannot obtain the required token. The server also rejects requests whose origin is not the widget’s exact origin.

Do not add permissive credentialed CORS rules to the token endpoint; that could undermine this boundary.

### What about third-party scripts?

**CSRF defenses do not protect against a malicious script executing inside the widget’s origin.** Such a script could obtain the token and make authenticated requests despite `HttpOnly`.

This example therefore:

- Loads only a local script under a restrictive CSP.
- Keeps the widget separate from the merchant’s scripts through the iframe’s cross-origin boundary.
- Limits embedding to the named merchant using `frame-ancestors`.

If you load vendor scripts directly into the widget, you are trusting them with its privileges. Prefer isolated, appropriately sandboxed iframes for less-trusted functionality.

Finally, **third-party-cookie blocking can still prevent this example from retaining its session**. `SameSite=None` does not override browser privacy settings; depending on the integration, you may need partitioned cookies, the Storage Access API, or a top-level authentication flow.
